package com.chance.bitlifediag;

import java.io.*;
import java.util.*;

/** Independent, character-scoped simulation. Base-game data is read-only. */
public final class ExpansionState implements Serializable {
    private static final long serialVersionUID=4L;
    public static final int SCHEMA=4;
    public String heroId,name,career=""; public int age,flags,ap=30;
    public long credits=25000,totalTax,totalEarned,streams,seed;
    public int musicSkill=20,productionSkill=20,fans=20,musicRep=10,studio=1;
    public String project="",genre="Alternative",distribution="Independent",label="";
    public int projectStage,quality,masterShare=100,releaseCounter;
    public ArrayList<Release> catalogue=new ArrayList<Release>();
    public long lastMusicIncome,lastSocialIncome,lastAssetIncome,lastTax;
    public int[] followers={20,0,0,0,0,0},trust={60,60,60,60,60,60};
    public int audienceLoyalty=30,brandRep=10,subscriberCount;
    public int jobSkill=15,workRep=20,workPerformance=30,workRank,projectsDone,burnout;
    public String assignment="",assignmentKind=""; public int assignmentStage,assignmentQuality;
    public String schoolCourse="Creative Arts",club="",peer="",sport="Football";
    public int knowledge=10,schoolAttendance=70,grades=40,schoolRep=20,qualifications,clubLevel,sportSkill=15,trophies;
    public int raceTier,driverSkill=15,raceRep=10,car=15,reliability=80,engineer=10,licence=0;
    public String team="Privateer",sponsor="",raceApproach="Balanced",tyres="Medium";
    public int round,season,points,wins,titles,totalRaces,contractYears,penaltyPoints;
    public int[] opponentPoints=new int[19]; public int[] rivals=new int[19];
    public boolean qualifyingDone,ownsTeam; public int grid; public String weather="Dry";
    public String tvTitle="",tvFormat="Talent",tvRole="Contestant";
    public int episode,tvSeason,tvRep=10,tvAudience=100,tvScore,alliances; public boolean tvActive;
    public int[] contestants=new int[9]; public boolean[] eliminated=new boolean[9];
    public ArrayList<Asset> assets=new ArrayList<Asset>();
    public ArrayList<String> history=new ArrayList<String>();
    public ArrayList<Event> pending=new ArrayList<Event>();
    public ArrayList<String> completed=new ArrayList<String>();
    public static final String[] PLATFORMS={"SoundCloud","YouTube","TikTok","Instagram","Podcast","Fan Club"};
    public static final String[] TIERS={"Karting","Regional Formula","Formula 3","Formula 2","Formula 1"};
    public static final String[] CIRCUITS={"Harbour Sprint","Desert Ring","Alpine Park","Coastal Circuit","Capital Streets","Forest Raceway","Sunset Oval","Rain Valley","Island Grand Prix","Metro Circuit","Highland Ring","World Finale"};
    public static final String[] DRIVERS={"Mia Vale","Leo Torres","Nora Hayes","Jasper Reed","Sofia Costa","Kai Chen","Amara Cole","Felix Stone","Zara Nash","Oscar Vega","Luca Bell","Ava Park","Noah Ellis","Iris Fox","Ethan Ross","Ruby Lane","Theo West","Skye Shaw","Max Grey"};
    public static final String[] TEAMS={"Privateer","Harbour Racing","Aurora Motorsport","Veloce Works","Apex Dynamics","Titan Grand Prix"};
    public static final String[] ASSET_NAMES={"Recording Studio","Creator Campus","Luxury Yacht","Private Island","Art Gallery","Racing Team HQ","Film Studio","Sports Academy"};
    public static final long[] ASSET_COST={50000,250000,1000000,5000000,750000,3000000,1500000,600000};
    public static final long[] ASSET_UPKEEP={1500,6500,35000,120000,14000,90000,42000,18000};
    public static class Release implements Serializable {private static final long serialVersionUID=1L; public String title,genre,type;public int quality,share,age;public long streams,royalties;}
    public static class Asset implements Serializable {private static final long serialVersionUID=1L;public int kind,condition=100;public long value;public String name;}
    public static class Event implements Serializable {private static final long serialVersionUID=1L;public int kind,year;public String title,body;public String[] choices;}
    public ExpansionState(String id,String who,int years,int f,long initialSeed){heroId=id;name=who;age=years;flags=f;seed=initialSeed;log("Expansion opened. Rookie fund: 25,000 credits. Your game bank balance is separate.");}
    private int random(int n){seed^=seed<<13;seed^=seed>>>7;seed^=seed<<17;return (int)((seed&Long.MAX_VALUE)%n);}
    private int clamp(int v){return Math.max(0,Math.min(100,v));}
    private int chance(int low,int high){return low+random(high-low+1);}
    public void log(String text){history.add("Age "+age+": "+text);while(history.size()>120)history.remove(0);}
    private void check(boolean ok,String why){if(!ok)throw new IllegalStateException(why);}
    private void living(){check((flags&8)!=0,"This life has ended. You can still view its history.");}
    private void free(){living();check((flags&4)==0,"This activity is unavailable while imprisoned.");}
    private void action(int energy,long cost){living();check(ap>=energy,"You need "+energy+" activity points. Age up to recover.");check(credits>=cost,"You need "+cost+" expansion credits.");ap-=energy;credits-=cost;}
    private void earn(long value){value=Math.max(0,Math.min(value,1000000000000L));credits+=value;totalEarned+=value;}
    public void sync(String who,String job,int f){name=who;career=job==null?"":job;flags=f;}
    public void advance(int target){check(target>=age,"Use a saved annual checkpoint to rewind.");check(target-age<=200,"Unexpected age jump. Reload your life.");while(age<target){age++;annual();}}
    private void annual(){
        ap=30;burnout=Math.max(0,burnout-15);qualifyingDone=false;
        lastMusicIncome=0;lastSocialIncome=0;lastAssetIncome=0;
        for(Release r:catalogue){int years=age-r.age;long play=Math.max(40,(long)(r.quality*30+fans*2)*(100+random(100))/(100L+years*35));r.streams+=play;streams+=play;long royalty=play*r.share/5000; r.royalties+=royalty;lastMusicIncome+=royalty;}
        fans=Math.min(100000000,fans+(int)Math.min(10000,lastMusicIncome/2));
        for(int i=0;i<6;i++){int keep=Math.max(10,70+trust[i]/4);followers[i]=(int)Math.min(100000000,(long)followers[i]*keep/100);lastSocialIncome+=(long)followers[i]*trust[i]/5000;}
        lastSocialIncome+=(long)subscriberCount*36;
        for(Asset a:assets){a.condition=Math.max(0,a.condition-chance(3,10));a.value=Math.max(1,a.value*(95+random(13))/100);long revenue=ASSET_UPKEEP[a.kind]*a.condition*(85+random(50))/10000;lastAssetIncome+=revenue-ASSET_UPKEEP[a.kind];}
        long income=lastMusicIncome+lastSocialIncome+Math.max(0,lastAssetIncome);
        lastTax=income<=10000?0: income<=100000?(income-10000)*15/100:13500+(income-100000)*30/100;
        totalTax+=lastTax;earn(income-lastTax+3500);credits=Math.max(0,credits+Math.min(0,lastAssetIncome));
        if(contractYears>0){earn((raceTier+1)*2500L);contractYears--;if(contractYears==0){team="Privateer";log("Your racing contract expired. Negotiate a new seat.");}}
        if(!sponsor.isEmpty()){earn((raceTier+1)*1500L);if(raceRep<15){log("Your sponsor withdrew after a poor reputation review.");sponsor="";}}
        if(!assignment.isEmpty()){workPerformance=clamp(workPerformance-8);log("Your unfinished work project lost momentum.");}
        if(tvActive){tvAudience=Math.max(100,tvAudience*90/100);log("Your unfinished TV season resumed with a smaller audience.");}
        for(int i=0;i<3;i++)queueEvent((age+i+random(7))%12);
        log("Annual accounts: music "+lastMusicIncome+", social "+lastSocialIncome+", assets "+lastAssetIncome+", tax "+lastTax+"; 30 activity points restored.");
    }
    private void queueEvent(int k){if(pending.size()>=12)return;Event e=new Event();e.kind=k;e.year=age;
        String[] titles={"The leaked demo","A sponsor's condition","A suspicious invoice","The school showcase","A paddock rumour","A reunion invitation","Your fans disagree","A midnight deadline","The reality TV edit","A neighbourhood project","A damaged archive","The charity match"};
        String[] bodies={"A rough mix circulates before your release. Fans argue about the unfinished sound.","A brand wants to approve everything you post for a year.","A supplier's bill includes a fee you never agreed to.","A local school invites you to help students stage a creative showcase.","A rival claims your recent pace is all down to expensive equipment.","Old classmates organise a reunion that clashes with a rehearsal.","Your audience wants a familiar sound while you want to experiment.","A client suddenly moves a project deadline to tomorrow morning.","A TV editor offers you a dramatic storyline that could hurt a friend's reputation.","Residents want to turn an empty building into a shared creative space.","Some old recordings have corrupted files. A specialist offers restoration.","A charity team asks you to play in a televised exhibition."};
        e.title=titles[k];e.body=bodies[k];e.choices=new String[]{"Invest time and handle it carefully","Pay for experienced help — 1,000 credits","Take a public risk","Decline and protect my time"};pending.add(e);
    }
    public String resolveEvent(int index,int choice){living();check(index>=0&&index<pending.size()&&choice>=0&&choice<4,"That event is no longer available.");Event e=pending.get(index);if(choice==0){action(2,0);musicRep=clamp(musicRep+2);workRep=clamp(workRep+3);audienceLoyalty=clamp(audienceLoyalty+3);}else if(choice==1){action(0,1000);brandRep=clamp(brandRep+4);schoolRep=clamp(schoolRep+3);}else if(choice==2){action(1,0);int result=chance(-12,16);musicRep=clamp(musicRep+result);raceRep=clamp(raceRep+result);if(result>0){earn(2500);fans+=150;}}else{ap=Math.min(30,ap+1);workRep=clamp(workRep-1);}pending.remove(index);String result=e.title+": "+e.choices[choice];log(result);return result;}
    public String beginMusic(String title,String style,String type){free();check(age>=10,"Start recording from age 10.");check(project.isEmpty(),"Finish or archive your current project first.");check(title!=null&&!title.trim().isEmpty(),"Give the project a title.");action(2,type.equals("Album")?2500:300);project=title.trim();if(project.length()>50)project=project.substring(0,50);genre=style;projectStage=0;quality=20+musicSkill/4+productionSkill/4;log("Started "+type+" project '"+project+"' in "+genre+".");projectType=type;return "Project created. Write, produce and mix before release.";}
    public String projectType="Single";
    public String musicStep(int mode){free();check(!project.isEmpty(),"Create a music project first.");check(projectStage<3,"Choose a distribution deal to release this project.");action(2,mode==1?500:0);int gain=mode==0?chance(3,10):mode==1?chance(8,16):chance(-6,20);quality=clamp(quality+gain+studio);musicSkill=clamp(musicSkill+2);productionSkill=clamp(productionSkill+2);projectStage++;String stage=new String[]{"Writing","Production","Mixing"}[projectStage-1];log(stage+" finished for '"+project+"': quality "+quality+".");return stage+" complete. Quality: "+quality+"/100.";}
    public String release(int deal,int promo){free();check(!project.isEmpty()&&projectStage==3,"Complete all three studio stages first.");check(deal>=0&&deal<3&&promo>=0&&promo<3,"Unknown release option.");action(1,new long[]{0,750,2500}[promo]);masterShare=deal==0?100:deal==1?75:35;distribution=new String[]{"Independent","Distribution partner","Record label"}[deal];
        long reach=(quality*40L+fans)*new int[]{1,2,4}[deal]*(1+promo);int listeners=(int)Math.min(1000000,reach/10);fans=Math.min(100000000,fans+listeners);followers[0]=Math.min(100000000,followers[0]+listeners/2);musicRep=clamp(musicRep+quality/12);Release r=new Release();r.title=project;r.genre=genre;r.type=projectType;r.quality=quality;r.share=masterShare;r.age=age;r.streams=reach;r.royalties=reach*masterShare/5000;catalogue.add(r);streams+=reach;earn(r.royalties+(deal==2?3000:0));releaseCounter++;log("Released '"+project+"' via "+distribution+"; "+masterShare+"% masters, "+reach+" streams.");project="";return r.title+" released. "+listeners+" new fans; "+masterShare+"% royalty share.";}
    public String musicAction(String kind){free();if(kind.equals("Practice")){action(2,100);musicSkill=clamp(musicSkill+chance(3,7));productionSkill=clamp(productionSkill+2);return record("Studio practice improved music skill to "+musicSkill+".");}
        if(kind.equals("Upgrade studio")){check(studio<5,"Your studio is fully equipped.");action(1,studio*5000);studio++;return record("Studio upgraded to level "+studio+". Future mixes gain quality.");}
        if(kind.equals("Collaborate")){check(!project.isEmpty()&&projectStage<3,"Collaborate during an unfinished project.");action(2,1200);quality=clamp(quality+chance(6,16));fans+=100;return record("A guest musician added a new hook to your project.");}
        if(kind.equals("Sell a beat")){action(2,100);long sale=productionSkill*20L+chance(100,700);earn(sale);productionSkill=clamp(productionSkill+2);return record("Licensed a beat for "+sale+" credits while retaining your catalogue.");}
        if(kind.equals("Play a show")){check(releaseCounter>0,"Release some music before booking a show.");action(3,600);long tickets=fans*(long)chance(1,4)/10;earn(tickets);fans+=chance(40,200);musicRep=clamp(musicRep+3);return record("Played a local show. Ticket income: "+tickets+" credits.");}
        if(kind.equals("Pitch a playlist")){check(releaseCounter>0,"Release music first.");action(1,150);boolean yes=chance(0,99)<musicRep;fans+=yes?600:20;return record(yes?"A curator featured your latest release. +600 fans.":"No playlist placement this time. Twenty listeners found your pitch.");}
        if(kind.equals("Found a label")){check(label.isEmpty(),"You already own a label.");check(musicRep>=45&&releaseCounter>=3,"Build 45 music reputation and release three projects.");action(3,30000);label=name+" Records";return record("Founded "+label+". Sign developing artists through label scouting.");}
        if(kind.equals("Scout an artist")){check(!label.isEmpty(),"Found a label first.");action(3,5000);int talent=chance(30,90);long fee=talent*chance(60,160);earn(fee);musicRep=clamp(musicRep+3);return record("Your label developed a new artist: talent "+talent+", first licensing income "+fee+".");}
        throw new IllegalStateException("Unknown studio activity.");}
    private String record(String s){log(s);return s;}
    public String social(int platform,int type){free();check(age>=13,"Social activities unlock at age 13.");check(platform>=0&&platform<6&&type>=0&&type<6,"Unknown social activity.");
        if(type==0){action(1,0);int gain=chance(10,80)+followers[platform]/10+musicRep;if(chance(0,99)<8){gain*=5;trust[platform]=clamp(trust[platform]-4);}followers[platform]=Math.min(100000000,followers[platform]+gain);brandRep=clamp(brandRep+1);return record(PLATFORMS[platform]+": a behind-the-scenes post gained "+gain+" followers.");}
        if(type==1){action(2,300);int gain=chance(80,240)+followers[platform]/6;followers[platform]=Math.min(100000000,followers[platform]+gain);trust[platform]=clamp(trust[platform]+3);return record(PLATFORMS[platform]+": creator collaboration brought "+gain+" followers.");}
        if(type==2){check(followers[platform]>=500,"Build 500 followers on this platform first.");action(2,0);long pay=followers[platform]*(long)chance(1,5)/8;earn(pay);trust[platform]=clamp(trust[platform]-chance(2,8));brandRep=clamp(brandRep+3);return record("Completed a disclosed "+PLATFORMS[platform]+" sponsorship for "+pay+" credits.");}
        if(type==3){action(2,100);trust[platform]=clamp(trust[platform]+8);audienceLoyalty=clamp(audienceLoyalty+4);return record("A live Q&A improved audience trust on "+PLATFORMS[platform]+".");}
        if(type==4){check(followers[platform]>=250,"Build 250 followers first.");action(2,500);int members=followers[platform]*audienceLoyalty/1000;subscriberCount+=members;return record("Launched a paid fan series. "+members+" subscribers; annual subscription income begins next year.");}
        action(1,0);trust[platform]=clamp(trust[platform]+10);followers[platform]=followers[platform]*97/100;return record("You moderated a controversy and published a correction. Trust rose; 3% unfollowed.");}
    public String workKind(){String c=career.toLowerCase(Locale.ROOT);if(c.contains("producer")||c.contains("director")||c.contains("sound")||c.contains("writer"))return "Creative";if(c.contains("engineer")||c.contains("scient")||c.contains("developer")||c.contains("data"))return "Technical";if(c.contains("police")||c.contains("trooper")||c.contains("inspector"))return "Public service";if(c.contains("teacher")||c.contains("tutor"))return "Education";return "Business";}
    public String beginWork(int choice){free();check((flags&2)!=0,"Get a job in the main game first.");check(assignment.isEmpty(),"Finish the current assignment first.");action(2,0);assignmentKind=workKind();String[][] names={{"Pilot episode","Artist session","Festival broadcast"},{"Prototype review","Data migration","Safety redesign"},{"Community outreach","Case review","Training exercise"},{"Classroom workshop","Student exhibition","Learning plan"},{"Client launch","Operations audit","New service proposal"}};int k=Arrays.asList("Creative","Technical","Public service","Education","Business").indexOf(assignmentKind);assignment=names[k][Math.floorMod(choice,3)];assignmentStage=0;assignmentQuality=20+jobSkill/3;return record("Started "+assignment+" for your "+career+" portfolio.");}
    public String workStep(int style){free();check((flags&2)!=0,"This life no longer has a main-game job.");check(!assignment.isEmpty(),"Choose an assignment first.");check(assignmentStage<3,"Submit your finished assignment.");action(style==2?3:2,style==1?500:0);assignmentQuality=clamp(assignmentQuality+new int[]{8,14,20}[Math.floorMod(style,3)]+chance(-3,6));burnout=clamp(burnout+(style==2?15:5));jobSkill=clamp(jobSkill+3);assignmentStage++;return record("Project stage "+assignmentStage+"/3 finished; quality "+assignmentQuality+", burnout "+burnout+".");}
    public String submitWork(){free();check((flags&2)!=0,"You need an active main-game job.");check(!assignment.isEmpty()&&assignmentStage==3,"Finish all three project stages.");action(1,0);int score=clamp(assignmentQuality-burnout/3);long bonus=score*30L;earn(bonus);workPerformance=clamp(workPerformance+score/8);workRep=clamp(workRep+score/10);projectsDone++;completed.add(assignment+" ("+score+")");while(completed.size()>30)completed.remove(0);String result=assignment+" scored "+score+". Expansion project bonus: "+bonus+" credits.";assignment="";return record(result);}
    public String workAction(int type){free();check((flags&2)!=0,"Get a job first.");if(type==0){action(2,400);jobSkill=clamp(jobSkill+8);return record("A specialist workshop improved your job skill.");}if(type==1){action(2,0);workRep=clamp(workRep+6);burnout=Math.max(0,burnout-5);return record("You mentored a coworker and shared your project templates.");}if(type==2){check(projectsDone>=(workRank+1)*2&&workRep>=30+workRank*10,"Complete more projects and improve your reputation before portfolio review.");action(2,0);workRank++;earn(workRank*5000L);return record("Your expansion portfolio advanced to rank "+workRank+". Main-game job promotions still use the game's own system.");}action(1,0);burnout=Math.max(0,burnout-20);return record("You set work boundaries and recovered from burnout.");}
    public String schoolAction(int type,String value){living();check((flags&4)==0,"School activities are unavailable while imprisoned.");if(type==0){action(2,age<18?0:500);schoolCourse=value;knowledge=clamp(knowledge+chance(5,12));schoolAttendance=clamp(schoolAttendance+4);return record("Studied "+schoolCourse+"; knowledge "+knowledge+".");}if(type==1){action(3,0);int score=clamp(knowledge*6/10+schoolAttendance/5+chance(0,20));grades=score;if(score>=65){qualifications++;earn(1000);return record("Passed the "+schoolCourse+" assessment: "+score+". Earned a certificate and a 1,000-credit bursary.");}return record("Assessment score "+score+". More study and attendance will help.");}if(type==2){action(2,100);club=value;clubLevel++;schoolRep=clamp(schoolRep+5);return record("Built a "+club+" club project. Club level "+clubLevel+".");}if(type==3){check(clubLevel>=2,"Develop a club project twice before entering.");action(3,300);boolean win=knowledge+schoolRep+chance(0,60)>115;if(win){trophies++;earn(3000);}return record(win?"Your club won the regional competition. +3,000 credits.":"Your team reached the regional competition and received useful feedback.");}if(type==4){action(2,0);peer=value;schoolRep=clamp(schoolRep+6);schoolAttendance=clamp(schoolAttendance+3);return record("You supported a peer through "+peer+". Community reputation improved.");}action(2,0);knowledge=clamp(knowledge+4);schoolAttendance=clamp(schoolAttendance+10);return record("A tutor helped organise your timetable and attendance.");}
    public String sports(int type,String selected){free();check(age>=6,"Join sports from age 6.");if(type==0){action(2,150);sport=selected;sportSkill=clamp(sportSkill+chance(5,10));return record("Trained "+sport+". Skill "+sportSkill+".");}if(type==1){check(sportSkill>=35,"Reach 35 sporting skill first.");action(3,300);boolean win=sportSkill+chance(0,60)>=85;if(win){trophies++;earn(5000);}else sportSkill=clamp(sportSkill+3);return record(win?"Won the "+sport+" regional tournament. +5,000 credits.":"Competed in "+sport+" and learned from stronger rivals.");}action(2,0);sportSkill=clamp(sportSkill+3);schoolRep=clamp(schoolRep+8);return record("Coached young athletes and strengthened your community standing.");}
    public String raceTraining(int type){free();check(age>=6,"Karting starts at age 6.");action(2,type==1?700:200);if(type==0)driverSkill=clamp(driverSkill+chance(4,8));else if(type==1)engineer=clamp(engineer+8);else {reliability=clamp(reliability+12);penaltyPoints=Math.max(0,penaltyPoints-2);}return record(new String[]{"Driver coaching","Engineer debrief","Safety and mechanics"}[Math.floorMod(type,3)]+" completed.");}
    public String upgradeCar(){free();check(car<100,"Your car is fully developed.");action(2,(raceTier+1)*2000L);car=clamp(car+9);reliability=Math.max(25,reliability-2);return record("Aero and chassis package installed. Pace "+car+"; reliability "+reliability+".");}
    public String signTeam(int index){free();check(index>=1&&index<6,"Choose a team.");check(age>=14||raceTier==0,"Formula contracts start at age 14.");check(raceRep>=index*10&&driverSkill>=index*12,"This team requires reputation "+index*10+" and skill "+index*12+".");action(1,0);team=TEAMS[index];contractYears=2;car=Math.max(car,20+index*10);return record("Signed a two-year seat with "+team+". Annual salary: "+((raceTier+1)*2500)+" credits.");}
    public String sponsor(){free();check(raceRep>=25&&totalRaces>=3,"Build 25 racing reputation and complete three races.");check(sponsor.isEmpty(),"Your sponsor contract is active.");action(2,0);sponsor="Nova Energy";earn((raceTier+1)*2500L);return record("Signed Nova Energy. An annual retainer begins next year.");}
    public String promoteTier(){free();check(raceTier<4,"You are already in Formula 1.");check(round==0||round==12,"Finish the current season before changing series.");check(age>=(raceTier==0?14:raceTier==3?18:16),"You are too young for the next series.");check(driverSkill>=25+raceTier*15&&raceRep>=20+raceTier*12&&totalRaces>=6*(raceTier+1),"Build more race experience, skill and reputation.");action(2,(raceTier+1)*3500L);raceTier++;licence=raceTier;round=0;points=0;Arrays.fill(opponentPoints,0);season++;team="Privateer";contractYears=0;return record("Earned your "+TIERS[raceTier]+" licence. A fresh 12-race championship begins.");}
    public String qualify(String strategy){free();check(age>=6,"Karting starts at age 6.");check(!qualifyingDone,"Qualifying is already complete. Run the race next.");if(round>=12){round=0;points=0;Arrays.fill(opponentPoints,0);season++;}action(1,(raceTier+1)*150L);weather=chance(0,99)<28?"Wet":"Dry";raceApproach=strategy;
        int pace=driverSkill+car/2+engineer/4-raceTier*13+chance(-20,20)+(strategy.equals("Attack")?8:strategy.equals("Conserve")?-5:0);grid=Math.max(1,Math.min(20,21-pace/6));qualifyingDone=true;return record(CIRCUITS[round]+" qualifying: P"+grid+", "+weather+". Choose tyres before racing.");}
    public String race(String rubber){free();check(qualifyingDone,"Complete qualifying first.");tyres=rubber;boolean correct=weather.equals("Wet")?rubber.equals("Wet"):!rubber.equals("Wet");int reliabilityRoll=chance(0,99);boolean dnf=reliabilityRoll>reliability-(raceApproach.equals("Attack")?10:0);int position=Math.max(1,Math.min(20,grid+chance(-5,6)+(correct?0:6)+(rubber.equals("Soft")&&weather.equals("Dry")?-1:0)+(raceApproach.equals("Conserve")?2:0)));int[] awards={25,18,15,12,10,8,6,4,2,1};int scored=dnf?0:position<=10?awards[position-1]:0;points+=scored;totalRaces++;raceRep=clamp(raceRep+(dnf?-2:scored>0?4:1));driverSkill=clamp(driverSkill+1);reliability=Math.max(20,reliability-chance(1,4));if(!dnf&&position==1){wins++;earn((raceTier+1)*3000L);}int[] order=new int[19];for(int i=0;i<19;i++)order[i]=i;for(int i=18;i>0;i--){int j=random(i+1),t=order[i];order[i]=order[j];order[j]=t;}for(int i=0;i<19;i++){int p=i+1;if(!dnf&&p>=position)p++;if(p<=10)opponentPoints[order[i]]+=awards[p-1];}String result=CIRCUITS[round]+": "+(dnf?"mechanical retirement":"P"+position)+", "+scored+" points.";round++;qualifyingDone=false;if(round==12){int rank=1;for(int p:opponentPoints)if(p>points)rank++;result+=" Championship position "+rank+" with "+points+" points.";if(rank==1){titles++;earn((raceTier+1)*12000L);raceRep=clamp(raceRep+10);}log("Completed "+TIERS[raceTier]+" season "+(season+1)+". "+result);}return record(result);}
    public String ownTeam(){free();check(!ownsTeam,"You already own a team.");check(titles>=1&&raceRep>=60,"Win a title and reach 60 racing reputation.");action(3,2000000);ownsTeam=true;team=name+" Motorsport";car=clamp(car+10);engineer=clamp(engineer+15);return record("Founded "+team+". Your engineering programme has expanded.");}
    public String rival(int who,boolean friendly){free();check(who>=0&&who<19,"Choose a driver.");action(1,0);rivals[who]=Math.max(-100,Math.min(100,rivals[who]+(friendly?10:-15)));raceRep=clamp(raceRep+(friendly?2:-2));if(friendly)engineer=clamp(engineer+1);return record((friendly?"Shared a debrief with ":"Publicly challenged ")+DRIVERS[who]+". Relationship "+rivals[who]+".");}
    public String startTV(String title,String format,String role){free();check(age>=18,"Reality TV opens at age 18.");check(!tvActive,"Finish your current season first.");action(3,role.equals("Producer")?5000:500);tvTitle=title.isEmpty()?"House of Chances":title;tvFormat=format;tvRole=role;episode=0;tvScore=0;alliances=0;tvActive=true;for(int i=0;i<9;i++){contestants[i]=chance(25,70);eliminated[i]=false;}return record("Started "+tvTitle+": "+format+", "+role+". Eight episodes, nine rival contestants.");}
    public String tvEpisode(int approach){free();check(tvActive,"Start a TV season first.");action(2,approach==2?1000:0);int gain=chance(5,20)+(approach==0?musicSkill/6:approach==1?alliances+schoolRep/10:brandRep/8);tvScore+=gain;if(approach==1)alliances++;tvAudience=Math.min(100000000,tvAudience+gain*chance(20,70));for(int i=0;i<9;i++)if(!eliminated[i])contestants[i]+=chance(3,15);episode++;
        int weakest=-1;for(int i=0;i<9;i++)if(!eliminated[i]&&(weakest<0||contestants[i]<contestants[weakest]))weakest=i;if(weakest>=0&&episode<8)eliminated[weakest]=true;
        String result="Episode "+episode+": audience "+tvAudience+", season score "+tvScore+".";
        if(episode==8){int rank=1;for(int i=0;i<9;i++)if(!eliminated[i]&&contestants[i]>tvScore)rank++;long payout=tvRole.equals("Producer")?tvAudience*3L:rank==1?50000:5000;earn(payout);tvRep=clamp(tvRep+10);followers[1]=Math.min(100000000,followers[1]+tvAudience/20);tvSeason++;tvActive=false;result+=" Finale rank "+rank+". "+payout+"-credit payout.";}return record(result);}
    public String tvPitch(){free();check(tvSeason>0,"Complete a season before pitching a follow-up.");action(2,500);long advance=tvRep*300L;earn(advance);return record("A network licensed your season concept for "+advance+" credits. Start another season to continue.");}
    public String buyAsset(int kind){free();check(kind>=0&&kind<8,"Unknown asset.");check(assets.size()<24,"Manage or sell an asset before adding more.");action(1,ASSET_COST[kind]);Asset a=new Asset();a.kind=kind;a.value=ASSET_COST[kind];a.name=ASSET_NAMES[kind];assets.add(a);return record("Bought "+a.name+". Annual upkeep "+ASSET_UPKEEP[kind]+"; income depends on condition.");}
    public String assetAction(int index,boolean sell){free();check(index>=0&&index<assets.size(),"That asset is no longer available.");Asset a=assets.get(index);if(sell){action(1,0);earn(a.value*a.condition/100);assets.remove(index);return record("Sold "+a.name+" at its current condition-adjusted valuation.");}action(1,ASSET_UPKEEP[a.kind]/2);a.condition=100;return record("Refurbished "+a.name+" to 100% condition.");}
    public byte[] encode() throws IOException {ByteArrayOutputStream b=new ByteArrayOutputStream();ObjectOutputStream o=new ObjectOutputStream(b);o.writeObject(this);o.close();return b.toByteArray();}
    public static ExpansionState decode(byte[] b) throws IOException,ClassNotFoundException {checkBytes(b);ObjectInputStream in=new ObjectInputStream(new ByteArrayInputStream(b));Object x=in.readObject();in.close();if(!(x instanceof ExpansionState))throw new IOException("Unexpected expansion save.");ExpansionState s=(ExpansionState)x;if(s.heroId==null||s.history==null||s.pending==null||s.catalogue==null)throw new IOException("Incomplete expansion save.");return s;}
    private static void checkBytes(byte[] b)throws IOException{if(b.length>2000000)throw new IOException("Expansion save exceeds its limit.");}
}
